<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Advanced Password Generator Online','description'=>'Generate strong customizable passwords with letters, numbers and symbols locally.','url'=>'https://smarttoolz.in/tools/password-generator-advanced/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><span class="tool-kicker">ADVANCED PASSWORD</span><h1>Advanced Password Generator</h1><p>Create customizable random passwords instantly in your browser.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Length<input id="n" type="number" min="4" max="128" value="20"></label><label><input id="u" type="checkbox" checked> Uppercase</label><label><input id="l" type="checkbox" checked> Lowercase</label><label><input id="d" type="checkbox" checked> Numbers</label><label><input id="s" type="checkbox" checked> Symbols</label><button id="go" class="tool-btn">Generate Password</button><input id="out" readonly style="margin-top:15px;width:100%;box-sizing:border-box;height:46px"><button id="copy" class="tool-btn" style="margin-top:10px">Copy</button></div></section></main><script>(()=>{const $=id=>document.getElementById(id);$('go').onclick=()=>{let chars=($('u').checked?'ABCDEFGHIJKLMNOPQRSTUVWXYZ':'')+($('l').checked?'abcdefghijklmnopqrstuvwxyz':'')+($('d').checked?'0123456789':'')+($('s').checked?'!@#$%^&*()-_=+[]{};:,.?':'');if(!chars){$('out').value='Select at least one character set.';return}let n=Math.min(128,Math.max(4,+$('n').value||20)),a=new Uint32Array(n);crypto.getRandomValues(a);$('out').value=[...a].map(x=>chars[x%chars.length]).join('')};$('copy').onclick=()=>navigator.clipboard.writeText($('out').value);$('go').click()})();</script><?php smarttoolz_tool_page_end(); ?>